import Client from '@/shared/api/client'

// The one client instance. client.ts is generated by `make api`; never edit it.
// Same-origin by default: Vite proxies /api in development. Set VITE_API_URL when
// the deployed API lives on another origin (it must be in backend/encore.app CORS).
// fetch is resolved per call so tests can stub the network boundary with vi.stubGlobal.
export const api = new Client(import.meta.env.VITE_API_URL ?? globalThis.location?.origin ?? '', {
  fetcher: (input, init) => globalThis.fetch(input, init),
})
